memories.forEach((m,i)=>{const b=document.createElement('button');b.className='world-label';b.setAttribute('aria-label',`${i+1}. yıldıza yolculuk: ${m.title}`);b.innerHTML=`<span class="target-ring" aria-hidden="true"></span><span class="world-name"><small>0${i+1}</small>${m.short}</span>`;b.onclick=()=>travelTo(i);$('#starLabels').append(b);labels.push(b);const stop=document.createElement('button');stop.textContent=`0${i+1}`;stop.setAttribute('aria-label',`${m.title} yıldızına git`);stop.title=m.title;stop.onclick=()=>travelTo(i);$('#routeStops').append(stop);stopButtons.push(stop);});
function activate(){if(started)return;started=true;document.body.classList.add('started');$('#navigation').hidden=false;$('#journeyHud').hidden=false;$('#intro').inert=true;$('#exploreCaption').hidden=false;$('#gestureHint').textContent='Sürükle, etrafına bak. Bir yıldız seç.';}
function flightTo(pos,toLook,onDone,label,index){if(flight||failed)return;activate();$('#arrival').hidden=true;$('#exploreCaption').hidden=true;document.body.classList.remove('at-star');document.body.classList.add('travelling');$('#flightStatus').hidden=false;$('#destination').textContent=label;const from=basePos.clone(),fromLook=baseLook.clone(),diff=pos.clone().sub(from);const c1=from.clone().addScaledVector(diff,.28).add(new THREE.Vector3(diff.length()*.035,Math.min(180,diff.length()*.055),0));const c2=pos.clone().add(new THREE.Vector3(-diff.length()*.025,Math.min(130,diff.length()*.035),Math.max(200,diff.length()*.14)));const curve=new THREE.CubicBezierCurve3(from,c1,c2,pos);pan.set(0,0);drift.set(0,0);document.querySelectorAll('#navigation button').forEach(b=>b.disabled=true);flight={start:performance.now(),duration:reduce?240:Math.min(4900,2700+diff.length()*.19),curve,fromLook,toLook:toLook.clone(),toPos:pos.clone(),done:onDone,index};if(reduce){basePos.copy(pos);baseLook.copy(toLook);}requestFrame();}
function destinationFor(i){const m=memories[i],r=m.radius;return mobile()?{pos:m.pos.clone().add(new THREE.Vector3(0,-r*.6,r*6.7)),target:m.pos.clone().add(new THREE.Vector3(0,-r*2.0,0))}:{pos:m.pos.clone().add(new THREE.Vector3(-r*2.0,r*.4,r*6.2)),target:m.pos.clone().add(new THREE.Vector3(-r*1.4,0,0))};}
function travelTo(i){if(flight)return;if(failed){renderMemory(i);openDialog($('#memoryDialog'));return;}if(i===current&&started){$('#arrival').hidden=false;return;}const d=destinationFor(i);flightTo(d.pos,d.target,()=>arrive(i),`${memories[i].short} yıldızına doğru`,i);}
function arrive(i){current=i;visited.add(i);document.body.classList.add('at-star');$('#arrivalIndex').textContent=`YILDIZ 0${i+1} · BİZİM EVRENİMİZ`;$('#arrivalTitle').textContent=memories[i].title;$('#arrivalText').textContent=memories[i].summary;$('#arrival').hidden=false;$('#exploreCaption').hidden=true;$('#readMemory').innerHTML=i===5&&visited.size===6?'Anıyı ve mektubu aç <span>↗</span>':'Anıyı aç <span>↗</span>';updateProgress();$('#nextStar>span:first-child').textContent=visited.size===6&&i===5?'Mektubuna git':'Sıradaki yıldıza';$('#gestureHint').textContent=mobile()?'Etrafına bakmak için sürükle.':'Bakışını değiştirmek için sürükle.';}
function updateConnections(){if(!connectionGroup)return;connectionGroup.children.slice().forEach(o=>{connectionGroup.remove(o);o.geometry.dispose();o.material.dispose();});for(let i=0;i<6;i++){const j=(i+1)%6;if(visited.has(i)&&visited.has(j)){const a=memories[i].pos,b=memories[j].pos,mid=a.clone().lerp(b,.5);mid.y+=a.distanceTo(b)*.035;const curve=new THREE.CatmullRomCurve3([a,mid,b]),g=new THREE.BufferGeometry().setFromPoints(curve.getPoints(60));connectionGroup.add(new THREE.Line(g,new THREE.LineBasicMaterial({color:0xc9b386,transparent:true,opacity:.2,depthWrite:false})));}}}
function updateProgress(){updateConnections();labels.forEach((b,i)=>{b.classList.toggle('visited',visited.has(i));b.classList.toggle('active',i===current);b.setAttribute('aria-label',`${i+1}. yıldıza yolculuk: ${memories[i].title}${visited.has(i)?', keşfedildi':''}`);});stopButtons.forEach((b,i)=>{b.classList.toggle('visited',visited.has(i));b.classList.toggle('active',i===current);b.setAttribute('aria-current',i===current?'step':'false');});$('#visitedCount').textContent=`${visited.size} / 6 anı keşfedildi`;}
function overview(){if(flight)return;if(!started)return;flightTo(homePos,homeLook,()=>{current=-1;document.body.classList.remove('at-star');$('#arrival').hidden=true;$('#exploreCaption').hidden=false;$('#nextStar>span:first-child').textContent=visited.size===6?'Mektubunu aç':'İlk yıldıza';$('#exploreCaption>p').innerHTML=visited.size===6?'Bütün yolların sonunda,<br><em>iyi ki biz.</em>':'Hangi anımıza<br><em>gitmek istersin?</em>';updateProgress();},'Gökyüzümüze dönüyoruz',-1);}
$('#begin').onclick=()=>travelTo(0);$('#previous').onclick=()=>travelTo(current<=0?5:current-1);$('#nextStar').onclick=()=>{if((current===5||current===-1)&&visited.size===6)letter();else travelTo((current+1)%6);};$('#overviewLink').onclick=overview;$('#returnHome').onclick=overview;$('.brand').onclick=e=>{e.preventDefault();overview();};$('#readMemory').onclick=()=>{renderMemory(current);openDialog($('#memoryDialog'));};
function renderMemory(i){const m=memories[i];$('#memoryIndex').textContent=`YILDIZ 0${i+1} · ÖRNEK ANI`;$('#memoryTitle').textContent=m.title;$('#memoryText').textContent=m.text;$('#artScript').innerHTML=m.script;$('#memoryArt').style.filter=`hue-rotate(${m.hue}deg)`;$('#memoryPagination').textContent=`0${i+1} / 06`;$('#nextMemory').innerHTML=visited.size===6&&i===5?'Mektubu aç <span>↗</span>':'Sıradaki yıldıza git <span>↗</span>';if(failed){current=i;visited.add(i);}}
function openDialog(d){lastFocus=document.activeElement;d.showModal();document.body.classList.add('dialog-open');}function closeDialog(d){d.close();}document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]')){document.body.classList.remove('dialog-open');if(lastFocus?.isConnected&&!lastFocus.closest('[hidden]'))lastFocus.focus({preventScroll:true});}requestFrame();});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d);}});});
$('#closeMemory').onclick=()=>closeDialog($('#memoryDialog'));$('#nextMemory').onclick=()=>{closeDialog($('#memoryDialog'));if(current===5&&visited.size===6)letter();else travelTo((current+1)%6);};
function memoryList(){$('#memoryList').innerHTML='';memories.forEach((m,i)=>{const b=document.createElement('button');b.innerHTML=`<small>0${i+1}</small><span>${m.title}</span><span class="list-status">${visited.has(i)?'✧':'↗'}</span>`;b.onclick=()=>{closeDialog($('#listDialog'));travelTo(i);};$('#memoryList').append(b);});openDialog($('#listDialog'));}$('#memoriesLink').onclick=memoryList;$('#fallbackMemories').onclick=memoryList;$('#closeList').onclick=()=>closeDialog($('#listDialog'));
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
function letter(){if(visited.size<6){toast(`Mektubuna ulaşmak için ${6-visited.size} yıldız daha keşfet.`);return;}if(flight)return;openDialog($('#letterDialog'));}$('#letterLink').onclick=letter;$('#closeLetter').onclick=()=>closeDialog($('#letterDialog'));$('#backToSky').onclick=()=>closeDialog($('#letterDialog'));
function setupPointer(){const el=renderer.domElement;el.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(reduce||flight)return;if(drag){pan.x=THREE.MathUtils.clamp(drag.px-(e.clientX-drag.x)*.0012,-.32,.32);pan.y=THREE.MathUtils.clamp(drag.py+(e.clientY-drag.y)*.001,-.22,.22);}else if(e.pointerType==='mouse'){drift.set((e.clientX/innerWidth-.5)*.035,(e.clientY/innerHeight-.5)*.025);}requestFrame();});el.addEventListener('pointerup',()=>drag=null);el.addEventListener('pointercancel',()=>drag=null);el.addEventListener('pointerleave',()=>{if(!drag){drift.set(0,0);requestFrame();}});}
function resize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio||1,mobile()?1.35:1.65));renderer.setSize(innerWidth,innerHeight);starField.material.uniforms.ratio.value=renderer.getPixelRatio();configurePositions();if(flight){flight=null;document.body.classList.remove('travelling');$('#flightStatus').hidden=true;}if(current>=0){const d=destinationFor(current);basePos.copy(d.pos);baseLook.copy(d.target);arrive(current);}else{basePos.copy(homePos);baseLook.copy(homeLook);if(started)$('#exploreCaption').hidden=false;}pan.set(0,0);requestFrame();}
function projectLabels(){camera.updateMatrixWorld();let active=null;if(current>=0&&!flight){const m=memories[current],p=m.pos.clone().project(camera);active={x:(p.x*.5+.5)*innerWidth,y:(-p.y*.5+.5)*innerHeight,r:memories[current].radius*innerHeight/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*camera.position.distanceTo(m.pos)),d:camera.position.distanceTo(m.pos)};}memories.forEach((m,i)=>{projected.copy(m.pos).project(camera);const x=(projected.x*.5+.5)*innerWidth,y=(-projected.y*.5+.5)*innerHeight;let visible=projected.z<1&&projected.z>-1&&x>30&&x<innerWidth-30&&y>110&&y<innerHeight-115;if(active&&i!==current&&camera.position.distanceTo(m.pos)>active.d&&Math.hypot(x-active.x,y-active.y)<active.r+30)visible=false;labels[i].style.transform=`translate(${x}px,${y+18}px) translate(-50%,-50%)`;labels[i].style.visibility=visible&&!flight&&i!==current?'visible':'hidden';labels[i].tabIndex=visible&&!flight&&i!==current?0:-1;labels[i].style.opacity=flight?'0':(!started&&mobile()&&y>innerHeight*.53?'.12':'1');});}
function frame(now){raf=0;if(document.hidden||failed)return;if(software&&!reduce&&now-lastFrame<30){requestFrame();return;}const dt=Math.min((now-lastFrame)/1000,.1);lastFrame=now;elapsed+=dt;let intensity=0;
 if(flight){const p=Math.min(1,(now-flight.start)/flight.duration),e=p*p*p*(p*(p*6-15)+10);if(!reduce){basePos.copy(flight.curve.getPoint(e));baseLook.lerpVectors(flight.fromLook,flight.toLook,e);intensity=Math.sin(p*Math.PI);camera.fov=55+intensity*12;camera.updateProjectionMatrix();}$('#flightProgress').style.width=p*100+'%';if(p===1){const done=flight.done;basePos.copy(flight.toPos);baseLook.copy(flight.toLook);flight=null;camera.fov=55;camera.updateProjectionMatrix();document.body.classList.remove('travelling');$('#flightStatus').hidden=true;document.querySelectorAll('#navigation button').forEach(b=>b.disabled=false);done();}}
 camera.position.copy(basePos);if(!reduce&&!flight){camera.position.x+=Math.sin(elapsed*.12)*1.5;camera.position.y+=Math.cos(elapsed*.17)*1.2;}
 look.copy(baseLook);if(!reduce&&!flight){const distance=camera.position.distanceTo(baseLook);look.x+=Math.tan(pan.x+drift.x)*distance;look.y+=Math.tan(pan.y-drift.y)*distance;}camera.lookAt(look);if(flight&&!reduce)camera.rotateZ(Math.sin((now-flight.start)/flight.duration*Math.PI)*.018);
 starField.material.uniforms.time.value=reduce?0:elapsed;worldStars.forEach((g,i)=>{g.userData.sphere.material.uniforms.time.value=reduce?0:elapsed;g.userData.sphere.rotation.y=reduce?0:elapsed*.015;g.userData.aura.material.opacity=.68+(reduce?0:Math.sin(elapsed*.4+i)*.06);if(g.userData.companion){const a=(reduce?0:elapsed*.045)+i;g.userData.companion.position.set(Math.cos(a)*2.6,Math.sin(a)*.6,Math.sin(a)*1.8);}if(!reduce)g.userData.orbit.rotation.z=elapsed*.008;});
 trail.material.opacity=intensity*.15;if(intensity>.01&&flight&&!reduce){const verts=trail.geometry.attributes.position.array,pts=starField.geometry.attributes.position.array;temp.copy(flight.toPos).sub(camera.position).normalize().multiplyScalar(-intensity*70);for(let i=0;i<1100;i++){const j=i*3,k=i*6;verts[k]=pts[j];verts[k+1]=pts[j+1];verts[k+2]=pts[j+2];verts[k+3]=pts[j]+temp.x;verts[k+4]=pts[j+1]+temp.y;verts[k+5]=pts[j+2]+temp.z;}trail.geometry.attributes.position.needsUpdate=true;}
 projectLabels();renderer.render(scene,camera);if(!reduce||flight)requestFrame();}
function requestFrame(){if(!raf&&!document.hidden&&!failed)raf=requestAnimationFrame(frame);}
function setMotion(v){reduce=v;document.body.classList.toggle('motion-reduced',v);$('#motion').setAttribute('aria-pressed',String(v));$('#motion').setAttribute('aria-label',v?'Hareketi aç':'Hareketi azalt');$('#motion').title=v?'Hareketi aç':'Hareketi azalt';if(v){pan.set(0,0);drift.set(0,0);if(flight){basePos.copy(flight.toPos);baseLook.copy(flight.toLook);flight.start=performance.now()-flight.duration;}}requestFrame();}$('#motion').onclick=()=>setMotion(!reduce);matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>setMotion(e.matches));
function fallback(message){failed=true;if(raf)cancelAnimationFrame(raf);document.body.classList.add('in-fallback');document.body.classList.remove('travelling');$('#fallback').hidden=false;if(message)$('#fallbackMessage').textContent=message;$('#starLabels').hidden=true;$('#flightStatus').hidden=true;$('#navigation').hidden=true;$('#arrival').hidden=true;$('#exploreCaption').hidden=true;}
let audio=null,master=null,soundOn=false;$('#sound').onclick=async()=>{try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=0;master.connect(audio.destination);[130.813,195.998,261.626,329.628].forEach((freq,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.detune.value=i*2-3;g.gain.value=.12/(i+1);o.connect(g);g.connect(master);o.start();});}await audio.resume();soundOn=!soundOn;master.gain.cancelScheduledValues(audio.currentTime);master.gain.setTargetAtTime(soundOn?.15:0,audio.currentTime,.65);$('#sound').setAttribute('aria-pressed',String(soundOn));$('#sound').setAttribute('aria-label',soundOn?'Gökyüzü sesini kapat':'Gökyüzü sesini aç');$('#sound span').textContent=soundOn?'Ses açık':'Ses kapalı';}catch(e){toast('Ses başlatılamadı. Yolculuğa sessiz devam edebilirsin.');}};
addEventListener('resize',resize,{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(raf)cancelAnimationFrame(raf);raf=0;if(flight)flight.pausedAt=performance.now();if(audio)audio.suspend();}else{if(flight?.pausedAt){flight.start+=performance.now()-flight.pausedAt;delete flight.pausedAt;}lastFrame=performance.now();requestFrame();if(soundOn&&audio)audio.resume();}});
try{init();setMotion(reduce);}catch(e){console.error('Gökyüzü başlatılamadı:',e);fallback();}
